import os
import json
from playwright.sync_api import sync_playwright
stub=open("stub.js").read(); real=open(os.environ.get("THREE_JS","node_modules/three/build/three.min.js")).read(); dm=open("lib/dm.js").read(); topo=open("lib/topo.js").read(); qr=open("lib/qrcode.js").read()
with sync_playwright() as p:
    br=p.chromium.launch(args=["--no-sandbox","--use-gl=angle","--use-angle=swiftshader","--enable-unsafe-swiftshader","--ignore-gpu-blocklist"]); ctx=br.new_context(viewport={"width":1100,"height":1500})
    ctx.add_init_script(stub); ctx.add_init_script("try{localStorage.setItem('trip3d_ck','1');localStorage.setItem('trip3d_q','high')}catch(e){}"); ctx.add_init_script('setInterval(()=>{var t=document.getElementById("tourbg");t&&t.remove()},50)')
    def r(b): return lambda route: route.fulfill(status=200,content_type="application/javascript",body=b)
    ctx.route("**/three.js/**", r(real)); ctx.route("**/datamaps*", r(dm)); ctx.route("**/topojson*", r(topo)); ctx.route("**/d3/**", r("/*d3*/")); ctx.route("**/qrcode*", r(qr))
    ctx.route("**/fonts.g*/**", lambda r: r.fulfill(status=200,content_type="text/css",body=""))
    pg=ctx.new_page(); errs=[]; pg.on("pageerror",lambda e:errs.append(str(e))); pg.on("console",lambda m: errs.append("C:"+m.text) if m.type=="error" else None); pg.on("dialog",lambda d:d.accept())
    pg.goto("http://localhost:8099/?nomaint=1"); pg.wait_for_timeout(1500)
    import json
    pg.evaluate("window.confirm=()=>true;localStorage.removeItem('trip3d_proj');openTool(true,'stand');$('intro').style.display='none';$('s2').style.display='block';wi=ST.findIndex(x=>x.k=='loc');wr()"); pg.wait_for_timeout(300)
    print("chips btns",pg.evaluate("[...document.querySelectorAll('#presets [data-cont]')].map(b=>b.textContent).join(' | ')"))
    pg.evaluate("document.querySelector('#presets [data-cont=samerica]').click()")
    print("ctys",pg.evaluate("[W.ctys.length,document.getElementById('chips').innerText]"))
    pg.evaluate("document.querySelector('#chips [data-rm]').click()"); print("after remove",pg.evaluate("[W.ctys.length,document.getElementById('chips').innerText]"))
    pg.evaluate("document.querySelector('#presets [data-cont=europe]').click()")
    pg.evaluate("document.getElementById('wnext').click()"); pg.wait_for_timeout(300)
    pg.evaluate("wi=ST.length-1;wr()"); print("summary",pg.evaluate("[...document.querySelectorAll('#s2 .rc')].map(r=>r.innerText.replace(/\\n/g,'=').slice(0,90)).join(' | ')"))
    pg.evaluate("document.getElementById('wnext').click()"); pg.wait_for_timeout(5000)
    print("built",pg.evaluate("[MULTI,multiNames.length,$('cin').value,crop&&crop.join(','),model.children.length]"))
    pj=pg.evaluate("JSON.stringify(getProj(false))"); print("proj bytes",len(pj))
    pg.evaluate("setCountry(countries['Italy']);MULTI=false;crop=null"); pg.wait_for_timeout(800)
    pg.evaluate("putProj(JSON.parse(%s))"%json.dumps(pj)); pg.wait_for_timeout(4000)
    print("restored",pg.evaluate("[MULTI,multiNames.length,$('cin').value,crop&&crop.join(','),PR.rings.length]"))
    pg.evaluate("setLang('en');openTool(true,'stand');$('s2').style.display='block';wi=ST.findIndex(x=>x.k=='loc');wr()"); pg.wait_for_timeout(300)
    pg.evaluate("document.querySelector('#presets [data-cont=africa]').click()"); print("en",pg.evaluate("[document.getElementById('chips').innerText,[...document.querySelectorAll('#presets [data-cont]')].map(b=>b.textContent).join(' | ')]"))
    print("errs",errs)
